#!/usr/bin/env node
import fs from "node:fs";
import path from "node:path";

const root = process.cwd();
const payload = {"electron/types.ts": "", "electron/services/settings.ts": "", "electron/services/providers.ts": "", "electron/services/agent.ts": "", "src/types.ts": "", "src/components/SettingsModal.tsx": ""};

function fail(msg) { console.error(`[v0.3] ERRO: ${msg}`); process.exit(1); }

for (const rel of Object.keys(payload)) {
  const file = path.join(root, rel);
  if (!fs.existsSync(file)) fail(`Arquivo não encontrado: ${rel}. Execute na raiz do droidios2.`);
}

for (const [rel, b64] of Object.entries(payload)) {
  const file = path.join(root, rel);
  const backup = `${file}.bak-v0.3`;
  if (!fs.existsSync(backup)) {
    fs.copyFileSync(file, backup);
    console.log(`[v0.3] backup: ${rel}.bak-v0.3`);
  }
  fs.writeFileSync(file, Buffer.from(b64, "base64").toString("utf8"), "utf8");
  console.log(`[v0.3] atualizado: ${rel}`);
}

console.log("");
console.log("Droid2iOS Agent Engine v0.3 aplicado.");
console.log("Recursos: multi-provedor, fallback de modelos, retry/backoff, checkpoint persistente.");
console.log("");
console.log("Agora rode:");
console.log("  npm run typecheck");
console.log("  npm run build");
